INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Besteht eine IPv4-Adresse aus 32 Bit?', 2, '[{"text": "Ja", "correct": true, "because": "IPv4 verwendet 32 Bit, aufgeteilt in 4 Oktette"}, {"text": "Nein", "correct": false, "because": "32 Bit ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird eine IPv4-Adresse immer in Hexadezimalform angegeben?', 2, '[{"text": "Nein", "correct": true, "because": "IPv4 wird in Dezimalform (z. B. 192.168.0.1) geschrieben"}, {"text": "Ja", "correct": false, "because": "Hexadezimal gilt für IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IPv4-Adresse mehr als 4 Oktette enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "IPv4 ist auf 4 Oktette (32 Bit) beschränkt"}, {"text": "Ja", "correct": false, "because": "Mehr als 4 Oktette wären nicht IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist 255.255.255.255 eine gültige IPv4-Adresse?', 2, '[{"text": "Ja", "correct": true, "because": "Sie ist die Broadcast-Adresse in IPv4"}, {"text": "Nein", "correct": false, "because": "Sie ist gültig, aber speziell verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IPv4-Adresse immer vier Zahlen zwischen 0 und 255 enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Jedes Oktett reicht von 0 bis 255"}, {"text": "Nein", "correct": false, "because": "Das ist die Definition des IPv4-Formats"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits hat ein einzelnes Oktett in einer IPv4-Adresse?', 2, '[{"text": "8 Bit", "correct": true, "because": "Ein Oktett entspricht 8 Bit"}, {"text": "16 Bit", "correct": false, "because": "Zu viel für ein Oktett"}, {"text": "4 Bit", "correct": false, "because": "Zu wenig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schreibweise ist für eine IPv4-Adresse korrekt?', 3, '[{"text": "192.168.1.1", "correct": true, "because": "Punktierte Dezimalschreibweise ist Standard"}, {"text": "192:168:1:1", "correct": false, "because": "Das ist IPv6-Format"}, {"text": "192-168-1-1", "correct": false, "because": "Falsche Trennzeichen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Oktette hat eine IPv4-Adresse?', 2, '[{"text": "4", "correct": true, "because": "IPv4 besteht aus 4 Oktetten"}, {"text": "6", "correct": false, "because": "Das gilt nicht für IPv4"}, {"text": "8", "correct": false, "because": "Zu viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zahl ist die höchste, die in einem IPv4-Oktett vorkommen kann?', 2, '[{"text": "255", "correct": true, "because": "8 Bit erlauben Werte von 0 bis 255"}, {"text": "999", "correct": false, "because": "Übersteigt 8 Bit"}, {"text": "127", "correct": false, "because": "Zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird für die Darstellung eines IPv4-Oktetts verwendet?', 2, '[{"text": "Dezimal", "correct": true, "because": "IPv4 nutzt Dezimalzahlen (0-255)"}, {"text": "Binär", "correct": false, "because": "Nur intern"}, {"text": "Hexadezimal", "correct": false, "because": "Typisch für IPv6"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat das Adressformat von IPv4?', 4, '[{"text": "32 Bit lang", "correct": true, "because": "IPv4 besteht aus 32 Bit"}, {"text": "4 Oktette", "correct": true, "because": "Aufgeteilt in 4 Teile"}, {"text": "Hexadezimalschreibweise", "correct": false, "because": "IPv4 nutzt Dezimal"}, {"text": "Werte von 0 bis 255 pro Oktett", "correct": true, "because": "8 Bit pro Oktett"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele sind korrekte IPv4-Adressen?', 3, '[{"text": "10.0.0.1", "correct": true, "because": "Gültige Dezimalschreibweise"}, {"text": "192.168.0.256", "correct": false, "because": "256 übersteigt 255"}, {"text": "172.16.254.1", "correct": true, "because": "Gültige Adresse"}, {"text": "1.2.3.4", "correct": true, "because": "Gültig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was charakterisiert das IPv4-Adressformat?', 4, '[{"text": "Punktierte Dezimalschreibweise", "correct": true, "because": "z. B. 192.168.1.1"}, {"text": "32 Bit insgesamt", "correct": true, "because": "4 Oktette à 8 Bit"}, {"text": "8 Oktette", "correct": false, "because": "Nur 4 Oktette"}, {"text": "Werte bis 255 pro Oktett", "correct": true, "because": "8-Bit-Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf das IPv4-Adressformat zu?', 3, '[{"text": "Es besteht aus 4 Zahlen", "correct": true, "because": "4 Oktette"}, {"text": "Jede Zahl ist 0-255", "correct": true, "because": "8 Bit pro Oktett"}, {"text": "Trennung durch Doppelpunkte", "correct": false, "because": "Punkte, nicht Doppelpunkte"}, {"text": "Binärschreibweise für Endnutzer", "correct": false, "because": "Dezimal ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formate sind für IPv4-Adressen ungültig?', 3, '[{"text": "192.168.1.1", "correct": false, "because": "Das ist gültig"}, {"text": "256.1.2.3", "correct": true, "because": "256 übersteigt 255"}, {"text": "10.0.0.300", "correct": true, "because": "300 übersteigt 255"}, {"text": "172.16.0.1", "correct": false, "because": "Das ist gültig"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine IPv4-Adresse hat 4 Oktette. b) Jedes Oktett hat 16 Bit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "4 Oktette, aber 8 Bit pro Oktett"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IPv4-Adressen werden mit Punkten getrennt. b) IPv4 nutzt Hexadezimalzahlen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Punkte ja, Hexadezimal nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IPv4-Adresse hat 32 Bit. b) Sie besteht aus 6 Oktetten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "32 Bit ja, 4 Oktette, nicht 6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) 192.168.1.1 ist eine gültige IPv4-Adresse. b) 192.168.1.1.1 ist eine gültige IPv4-Adresse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "4 Oktette ja, 5 nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch "}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) IPv4-Adressen haben Werte von 0 bis 255 pro Oktett. b) IPv4-Adressen können 128 Bit lang sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "0-255 ja, 128 Bit ist IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

